        internal static BossRewardProfile[] CreateObliviaxRewards()
        {
            var hunt = new BossRewardAction(BossRewardActionKind.NativeDamage,BossObliviaxBalance.RewardHuntValueMilli,BossObliviaxBalance.RewardHuntCapMilli);
            var step = new BossRewardAction(BossRewardActionKind.NativeState,BossObliviaxBalance.RewardStepValueMilli,BossObliviaxBalance.RewardStepCapMilli,durationMillis:BossObliviaxBalance.RewardStepDurationMillis,rangeMilli:BossObliviaxBalance.RewardStepRangeMilli,order:1);
            var stun = new BossRewardAction(BossRewardActionKind.NativeState,BossObliviaxBalance.RewardStunValueMilli,BossObliviaxBalance.RewardStunCapMilli,order:2);
            return new[] { new BossRewardProfile(ObliviaxRewardId,ObliviaxSetId,"St_U_ShoutOfOblivion",BossRewardAdapter.ShoutOfOblivion,new[]
            {
                new BossRewardStage(1,new Txt("自身のシャウトスキルの狩猟倍率に、現在の狩猟レベル（0〜5）1ごとに0.03が加算される。加算は最大で0.15までで、狩猟レベルが0のときは加算されない。会心の発生条件や他の記憶は変わらない。", "Increase your Shout skill's hunting multiplier by 0.03 per current hunting level (0–5), up to a +0.15 bonus. Hunting level 0 grants no bonus. Critical hit conditions and other memories remain unchanged."),new[] { hunt }),
                new BossRewardStage(2,new Txt("固有報酬の段階1の効果に加え、シャウトスキルの後退距離が4mから5mに延びる（追加の上限は1m）。所要時間は0.4秒で、地形を貫通しない挙動は変わらない。", "In addition to boss reward stage 1, extend your Shout skill's backward movement from 4m to 5m, adding at most 1m. It still takes 0.4 seconds and cannot pass through terrain."),new[] { hunt,step }),
                new BossRewardStage(3,new Txt("固有報酬の段階2の効果に加え、シャウトスキルが命中したときのスタン時間が0.4秒延びる。ボスと行動妨害が効かない敵を除く敵に対し、1回の発動につき1体あたり1回だけ有効である。無敵時間は延びない。", "In addition to boss reward stage 2, extend the stun inflicted by your Shout skill by 0.4 seconds. This applies once per enemy per use, except bosses and enemies immune to crowd control. Invulnerability duration is not extended."),new[] { hunt,step,stun }),
            }) };
        }
